import 'package:flutter/material.dart';import '../../core/theme/app_colors.dart';import '../../core/widgets/ui.dart';import '../../data/app_data.dart';import '../../models/place.dart';import '../../state/app_state.dart';
class MapScreen extends StatelessWidget{const MapScreen({super.key});@override Widget build(BuildContext c){final st=AppScope.of(c),d=places.firstWhere((x)=>x.id==st.dest),g=gates.firstWhere((x)=>x.id==st.gate);return SafeArea(child:Column(children:[Container(color:AppColors.green,padding:const EdgeInsets.all(14),width:double.infinity,child:const Text('خريطة الحرم',style:TextStyle(color:Colors.white,fontSize:19,fontWeight:FontWeight.w800))),Expanded(child:ListView(padding:const EdgeInsets.all(14),children:[AppCard(padding:const EdgeInsets.all(8),child:Column(children:[Align(alignment:Alignment.centerRight,child:Text('أنت عند: ${g.name}',style:const TextStyle(fontWeight:FontWeight.w800))),AspectRatio(aspectRatio:400/440,child:CustomPaint(painter:HaramPainter(g,d)))])),const SizedBox(height:12),const Text('وجهتي',style:TextStyle(fontWeight:FontWeight.w800)),Wrap(spacing:7,children:places.map((p)=>ChoiceChip(selected:st.dest==p.id,label:Text(p.name),onSelected:(_)=>st.change(()=>st.dest=p.id))).toList()),const SizedBox(height:12),const Text('مكاني (اضغط بابًا)',style:TextStyle(fontWeight:FontWeight.w800)),Wrap(spacing:7,children:gates.map((p)=>ChoiceChip(selected:st.gate==p.id,label:Text(p.name),onSelected:(_)=>st.change(()=>st.gate=p.id))).toList()),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('الطريق إلى ${d.name}',style:const TextStyle(fontWeight:FontWeight.w800)),const Text('اتبع الخط الذهبي المتقطع. اتجه للمطاف أولًا ثم أكمل بحسب اللافتات الخضراء والأرقام على الأعمدة.',style:TextStyle(color:AppColors.muted))]))]))]));}}
class HaramPainter extends CustomPainter{final Place from,to;HaramPainter(this.from,this.to);@override void paint(Canvas c,Size s){final sx=s.width/400,sy=s.height/440;Offset o(Place p)=>Offset(p.x*sx,p.y*sy);c.drawRect(Offset.zero&s,Paint()..color=const Color(0xFFE4EBE3));c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(30*sx,80*sy,300*sx,300*sy),Radius.circular(30*sx)),Paint()..color=const Color(0xFFFBFCF9));final center=Offset(200*sx,230*sy);for(final r in [52.0,82,112])c.drawCircle(center,r*sx,Paint()..style=PaintingStyle.stroke..strokeWidth=1.2..color=AppColors.gold.withValues(alpha:.6));c.drawRect(Rect.fromCenter(center:center,width:32*sx,height:32*sy),Paint()..color=Colors.black);final path=Path()..moveTo(o(from).dx,o(from).dy);if((from.x-to.x).abs()>40&&(from.y-to.y).abs()>40)path.lineTo(to.x*sx,from.y*sy);path.lineTo(o(to).dx,o(to).dy);c.drawPath(path,Paint()..style=PaintingStyle.stroke..strokeWidth=5..strokeCap=StrokeCap.round..color=AppColors.gold);for(final p in gates){c.drawCircle(o(p),9,Paint()..color=AppColors.green);}c.drawCircle(o(to),11,Paint()..color=AppColors.gold);c.drawCircle(o(from),8,Paint()..color=const Color(0xFF2F7BFF));}@override bool shouldRepaint(covariant HaramPainter old)=>old.from.id!=from.id||old.to.id!=to.id;}
